package com.metaverse.coin.strategy.core.arbitrage.multi;

import com.metaverse.coin.strategy.common.dao.mapper.*;
import com.metaverse.coin.strategy.common.model.arbitrage.entity.*;
import org.springframework.stereotype.Service;
import java.util.Date;
import com.baomidou.mybatisplus.core.conditions.query.LambdaQueryWrapper;
import com.metaverse.coin.strategy.core.arbitrage.config.MultiExchangeFundingRateProperties;
import java.math.BigDecimal;
import java.util.Map;

@Service
public class CrossExchangeArbitragePersistenceService {
 private final CrossExchangeArbOpportunityMapper opportunities; private final CrossExchangeArbPositionMapper positions; private final CrossExchangeArbOrderMapper orders; private final CrossExchangeRiskSnapshotMapper risks; private final Map<Exchange,ExchangeCost> costs;
 public CrossExchangeArbitragePersistenceService(CrossExchangeArbOpportunityMapper o,CrossExchangeArbPositionMapper p,CrossExchangeArbOrderMapper r,CrossExchangeRiskSnapshotMapper risks,MultiExchangeFundingRateProperties properties){opportunities=o;positions=p;orders=r;this.risks=risks;this.costs=properties.getCosts();}
 public void saveOpportunity(CrossExchangeOpportunity o){CrossExchangeArbOpportunityEntity row=new CrossExchangeArbOpportunityEntity().setOpportunityCode(o.opportunityId()).setSymbol(o.symbol()).setLongExchange(o.longQuote().exchange().name()).setShortExchange(o.shortQuote().exchange().name()).setLongFundingRate(o.longQuote().rawFundingRate()).setShortFundingRate(o.shortQuote().rawFundingRate()).setHourlyFundingSpread(o.hourlyFundingSpread()).setEstimatedNetYield(o.estimatedNetYield()).setExecutableNotional(o.executableNotional()).setStatus(o.status().name()).setRejectionReason(o.rejectionReason()).setDiscoveredAt(Date.from(o.discoveredAt())).setUpdatedAt(new Date());CrossExchangeArbOpportunityEntity existing=opportunities.selectOne(new LambdaQueryWrapper<CrossExchangeArbOpportunityEntity>().eq(CrossExchangeArbOpportunityEntity::getOpportunityCode,o.opportunityId()));if(existing==null)opportunities.insert(row);else{row.setId(existing.getId());opportunities.updateById(row);}}
 public void savePosition(PaperHedgePosition p){Date now=new Date();CrossExchangeArbPositionEntity row=new CrossExchangeArbPositionEntity().setPositionCode(p.positionId()).setOpportunityCode(p.opportunity().opportunityId()).setSymbol(p.opportunity().symbol()).setLongExchange(p.opportunity().longQuote().exchange().name()).setShortExchange(p.opportunity().shortQuote().exchange().name()).setHedgedQuantity(p.hedgedQuantity()).setStatus(p.status().name()).setOpenedAt(p.openedAt()==null?null:Date.from(p.openedAt())).setClosedAt(p.status()==PaperHedgePosition.Status.CLOSED?Date.from(p.updatedAt()):null).setMessage(p.message()).setCreatedAt(now).setUpdatedAt(now);CrossExchangeArbPositionEntity existing=positions.selectOne(new LambdaQueryWrapper<CrossExchangeArbPositionEntity>().eq(CrossExchangeArbPositionEntity::getPositionCode,p.positionId()));if(existing==null)positions.insert(row);else{row.setId(existing.getId()).setCreatedAt(existing.getCreatedAt());positions.updateById(row);}saveOrder(p.positionId(),p.longOrder());saveOrder(p.positionId(),p.shortOrder());}
 private void saveOrder(String positionCode,PaperOrder o){if(o==null)return;if(orders.selectOne(new LambdaQueryWrapper<CrossExchangeArbOrderEntity>().eq(CrossExchangeArbOrderEntity::getClientOrderId,o.clientOrderId()))!=null)return;BigDecimal notional=o.filledQuantity().multiply(o.averagePrice());ExchangeCost cost=costs.get(o.leg().exchange());BigDecimal fee=cost==null?BigDecimal.ZERO:notional.multiply(cost.takerFeeRate());orders.insert(new CrossExchangeArbOrderEntity().setPositionCode(positionCode).setClientOrderId(o.clientOrderId()).setExchangeName(o.leg().exchange().name()).setSymbol(o.leg().symbol()).setLegSide(o.leg().side().name()).setReduceOnly(o.reduceOnly()).setRequestedQuantity(o.requestedQuantity()).setFilledQuantity(o.filledQuantity()).setAveragePrice(o.averagePrice()).setFeeAmount(fee).setStatus(o.status().name()).setMessage(o.message()).setCreatedAt(Date.from(o.updatedAt())).setUpdatedAt(Date.from(o.updatedAt())));}
 public void saveOrders(String positionCode,java.util.Collection<PaperOrder> all){for(PaperOrder o:all)if(o.clientOrderId().startsWith(positionCode+"-"))saveOrder(positionCode,o);}
 public void saveRisk(String positionCode,String opportunityCode,String stage,boolean passed,String reason){risks.insert(new CrossExchangeRiskSnapshotEntity().setPositionCode(positionCode).setOpportunityCode(opportunityCode).setCheckStage(stage).setPassed(passed).setReason(reason).setCreatedAt(new Date()));}
}
